      "required": [
        "message"
      ]
    }
  ]
}

{
  "description": "[https://www.rfc-editor.org/rfc/rfc7519](https://www.rfc-editor.org/rfc/rfc7519)\n",
  "type": "object",
  "properties": {
    "iss": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1)\n",
      "type": "string"
    },
    "exp": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4)\n",
      "type": "number"
    },
    "nbf": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5)\n",
      "type": "number"
    },
    "aud": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3)\n",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "iat": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6)\n",
      "type": "number"
    }
  },
  "required": [
    "iss",
    "exp",
    "nbf"
  ]
}

{
